INSERT INTO ai_rules (id, rule_text, source_count, active, created_at, updated_at) VALUES
('rule-0019', 'לפתוח כתבה עם תרחיש שהקורא כבר מזהה אצלו, לא עם הגדרה של הנושא.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0020', 'לומר במשפט אחד, מוקדם בכתבה, מה העיקרון המרכזי שהכל נובע ממנו, ולהצהיר בפירוש שזה הדבר הכי חשוב לזכור.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0021', 'לדרג עצות ממדריך ארוך מהקל והכללי ביותר לספציפי והמתקדם ביותר, כך שקורא שרוצה רק בסיס יכול לעצור באמצע ולקבל ערך.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0022', 'שלבים ממוספרים, כל שלב עם תווית קצרה מודגשת ואז משפט עד שלושה משפטים שמסבירים, בלי להסתמך על שלבים מאוחרים יותר כדי להבין.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0023', 'לפני הסיום, לנפץ מיתוס אחד או שניים בתבנית קצרה: מה חושבים בטעות, ומה נכון בפועל, בלי הרחבה מיותרת.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z'),
('rule-0024', 'לסיים בחזרה קצרה על העיקרון המרכזי מתחילת הכתבה, ואז הזמנה רכה לצעד הבא, לא מכירה תחת לחץ.', 1, 1, '2026-09-02T00:00:00.000Z', '2026-09-02T00:00:00.000Z');
